<script setup lang="ts">
import { ref } from 'vue'
import type { RecognitionResult } from '../api/review'
import { qualityText } from '../api/review'
defineProps<{ result: RecognitionResult; fileId: string; imageNumber?: number; source?: boolean }>()
const active = ref('')
function points(polygon: number[][]) { return polygon.map(point => point.join(',')).join(' ') }
function strategy(stages: string[]) { const labels = stages.filter(stage => !stage.startsWith('tile-')).map(stage => ({ mobile960:'标准识别', mobile1600:'高分辨率' }[stage] ?? stage)); const tiles = stages.filter(stage => stage.startsWith('tile-')).length; if (tiles) labels.push(`分块${tiles}次`); return labels.join(' → ') }
</script>
<template><section class="ocr-evidence"><div v-if="result.processingStrategy" class="ocr-strategy"><strong>{{ strategy(result.processingStrategy) }}</strong><el-tag :type="result.processingCoverageStatus === 'PARTIAL' ? 'warning' : 'info'">{{ result.processingCoverageStatus === 'PARTIAL' ? '部分区域已处理' : '处理完成' }}</el-tag></div><details v-if="result.conflictingOcrAlternatives?.length"><summary>识别差异 · {{ result.conflictingOcrAlternatives.length }}处</summary><el-table :data="result.conflictingOcrAlternatives"><el-table-column prop="retained" label="保留文字"/><el-table-column prop="alternative" label="其他候选"/></el-table></details><div v-if="result.originalWidth && result.originalHeight" class="ocr-image"><svg :viewBox="`0 0 ${result.originalWidth} ${result.originalHeight}`" role="img" :aria-label="`配图${imageNumber ?? ''} OCR识别区域`"><image :href="`/api/files/${fileId}`" :width="result.originalWidth" :height="result.originalHeight" /><polygon v-for="line in result.recognitionLines ?? []" :key="line.lineId" :points="points(line.polygon)" :class="{ selected: active === line.lineId }"><title>{{ line.text }}</title></polygon></svg></div><el-alert v-if="result.ocrStatus === 'EMPTY' || (result.ocrStatus && !result.recognitionLines?.length)" title="未识别到文字" type="warning" :closable="false" /><el-alert v-if="result.textSearchStatus === 'FAILED'" :title="`识别结果已保留，文字检索失败：${result.textSearchErrorCode || '请重试'}`" type="error" :closable="false" /><el-table v-if="result.recognitionLines?.length" :data="result.recognitionLines" size="small" @row-mouse-enter="(row: {lineId: string}) => active = row.lineId" @row-mouse-leave="active = ''"><el-table-column prop="text" label="识别文字" min-width="180" /><el-table-column label="识别置信度" width="110"><template #default="{row}">{{ row.confidence.toFixed(3) }}<span v-if="result.lowConfidenceLineIds?.includes(row.lineId)" class="unsaved"> 低</span></template></el-table-column></el-table><p v-if="qualityText(result.qualityFlags ?? [])" class="muted">识别状态：{{ qualityText(result.qualityFlags ?? []) }}</p><p v-if="!source">文字检索：{{ result.textSearchStatus === 'COMPLETED' ? '已完成' : result.textSearchStatus === 'FAILED' ? '失败' : '未运行' }}</p></section></template>

<style scoped>.ocr-strategy{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:14px 0;flex-wrap:wrap}.ocr-strategy strong{font-size:14px}</style>
